function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let breakRecords = [];

  // 現在進行中の作業記録を取得
  async function loadCurrentWorkRecord() {
    const workRecords = await window.aivicApi.list(1); // 作業記録テーブル
    if (!workRecords) return;

    // 終了時刻がnullの作業中レコードを取得
    currentWorkRecord = workRecords.find(r => !r.作業終了時刻);

    if (currentWorkRecord) {
      // 中断記録も取得
      const allBreakRecords = await window.aivicApi.list(2); // 中断記録テーブル
      if (allBreakRecords) {
        breakRecords = allBreakRecords.filter(b => b.作業記録ID === currentWorkRecord.作業記録ID);
      }

      displayWorkRecord();
    }
  }

  // 作業記録情報を画面に表示
  function displayWorkRecord() {
    if (!currentWorkRecord) return;

    container.querySelector('#work-item-name').textContent = currentWorkRecord.作業種別 || '-';
    container.querySelector('#work-location').textContent = currentWorkRecord.作業場所 || '-';

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    container.querySelector('#start-time').textContent = startTime.toLocaleString('ja-JP');

    // 現在時刻を終了時刻の初期値に設定
    const now = new Date();
    const endTimeInput = container.querySelector('#end-time');
    endTimeInput.value = now.toISOString().slice(0, 16);

    updateTimeCalculation();
  }

  // 時間計算を更新
  function updateTimeCalculation() {
    if (!currentWorkRecord) return;

    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const endTimeInput = container.querySelector('#end-time');

    if (endTimeInput.value) {
      const endTime = new Date(endTimeInput.value);
      const totalMinutes = Math.floor((endTime - startTime) / (1000 * 60));

      // 中断時間の合計を計算
      let breakMinutes = 0;
      breakRecords.forEach(b => {
        if (b.中断時間) {
          breakMinutes += b.中断時間;
        }
      });

      const actualMinutes = totalMinutes - breakMinutes;

      container.querySelector('#total-work-time').textContent = `${Math.floor(totalMinutes / 60)}時間${totalMinutes % 60}分`;
      container.querySelector('#break-time').textContent = `${Math.floor(breakMinutes / 60)}時間${breakMinutes % 60}分`;
      container.querySelector('#actual-work-time').textContent = `${Math.floor(actualMinutes / 60)}時間${actualMinutes % 60}分`;
    }
  }

  // 異常報告チェックボックスの制御
  container.querySelector('#has-issue').addEventListener('change', (e) => {
    const issueSection = container.querySelector('#issue-section');
    if (e.target.checked) {
      issueSection.style.display = 'block';
    } else {
      issueSection.style.display = 'none';
      container.querySelector('#issue-content').value = '';
    }
  });

  // 終了時刻変更時の時間再計算
  container.querySelector('#end-time').addEventListener('change', updateTimeCalculation);

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    if (!currentWorkRecord) {
      alert('作業記録が見つかりません');
      return;
    }

    const endTimeInput = container.querySelector('#end-time');
    if (!endTimeInput.value) {
      alert('終了時刻を入力してください');
      return;
    }

    const endTime = new Date(endTimeInput.value);
    const startTime = new Date(currentWorkRecord.作業開始時刻);
    const workMinutes = Math.floor((endTime - startTime) / (1000 * 60));

    if (workMinutes <= 0) {
      alert('終了時刻は開始時刻より後に設定してください');
      return;
    }

    const workMemo = container.querySelector('#work-memo').value;
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value;

    if (hasIssue && !issueContent.trim()) {
      alert('異常・問題の内容を入力してください');
      return;
    }

    // 作業記録を更新
    const updateData = {
      作業終了時刻: endTime.toISOString(),
      作業時間: workMinutes,
      作業内容: workMemo || currentWorkRecord.作業内容,
      進捗状況: completionStatus,
      備考: hasIssue ? `【異常報告】${issueContent}` : (currentWorkRecord.備考 || ''),
      更新日時: new Date().toISOString()
    };

    const updated = await window.aivicApi.update(1, currentWorkRecord.作業記録ID, updateData);

    if (updated) {
      // 異常値検出ログの作成（長時間作業の場合）
      if (workMinutes > 480) { // 8時間超過
        await window.aivicApi.save(4, {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: '作業記録',
          検出対象レコードID: currentWorkRecord.作業記録ID,
          ユーザーID: currentWorkRecord.作業員ID,
          異常値種別: '長時間作業',
          検出項目: '作業時間',
          検出値: `${workMinutes}分`,
          閾値: '480分',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }

      alert('工数記録を完了しました');
      // メイン画面に戻る
      window.showScreen('main');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('記録を完了せずに戻りますか？')) {
      window.showScreen('main');
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-view-record').addEventListener('click', () => {
    window.showScreen("scr-1778907226171");
  });

  // 初期データ読み込み
  loadCurrentWorkRecord();
}
